// === engine.js — Racing Game ===
// Main game loop, state machine, canvas bootstrap, camera, and math utilities.
// Attaches all exports to window.R.

window.R = window.R || {};

// ---------------------------------------------------------------------------
// Default engine constants (extend R.CONFIG if not already set)
// ---------------------------------------------------------------------------
R.CONFIG = R.CONFIG || {};
R.CONFIG.CANVAS_WIDTH        = R.CONFIG.CANVAS_WIDTH        || 1280;
R.CONFIG.CANVAS_HEIGHT       = R.CONFIG.CANVAS_HEIGHT       || 720;
R.CONFIG.MAX_DT              = R.CONFIG.MAX_DT              || 33;    // ms — cap to avoid spiral of death
R.CONFIG.CAMERA_SMOOTH       = R.CONFIG.CAMERA_SMOOTH       || 0.08;  // lerp factor per frame
R.CONFIG.CAMERA_OFFSET_Y     = R.CONFIG.CAMERA_OFFSET_Y     || -80;   // vertical offset from player
R.CONFIG.FINISH_DELAY        = R.CONFIG.FINISH_DELAY        || 5;     // seconds before restart allowed
R.CONFIG.COUNTDOWN_DURATION  = R.CONFIG.COUNTDOWN_DURATION  || 3;     // seconds of countdown

// ---------------------------------------------------------------------------
// Object pools / shared arrays — pre-allocated, no allocations in hot path
// ---------------------------------------------------------------------------
R.aiCars          = [];
R.particles       = [];
R.sceneryObjects  = [];

// ---------------------------------------------------------------------------
// Internal helpers (not exported)
// ---------------------------------------------------------------------------

/**
 * Safe no-op stub for optional systems that have not been loaded yet.
 * @param {string} name System name for console warning
 * @returns {Function} No-op function
 */
function _safeStub(name) {
  return function () { /* no-op: ' + name + ' not loaded */ };
}

/**
 * Safely invoke a function on R if it exists, otherwise use a no-op.
 * Used so the engine runs even when optional module files are missing.
 */
function _callIfExists(fnName) {
  if (typeof R[fnName] === 'function') {
    R[fnName]();
  }
}

// ---------------------------------------------------------------------------
// R.init() — Bootstrap the entire game
// ---------------------------------------------------------------------------

/**
 * Create the canvas element, initialise all subsystems, and start the
 * game loop.  Safe to call multiple times — subsequent calls are ignored.
 */
R.init = function () {
  if (R._initialised) return;
  R._initialised = true;

  // --- canvas element -------------------------------------------------
  const canvas = document.createElement('canvas');
  canvas.id          = 'gameCanvas';
  canvas.width       = R.CONFIG.CANVAS_WIDTH;
  canvas.height      = R.CONFIG.CANVAS_HEIGHT;
  canvas.style.display = 'block';
  canvas.style.margin  = '0 auto';
  canvas.style.background = '#000';
  canvas.style.maxWidth   = '100%';
  canvas.style.maxHeight  = '100vh';
  canvas.style.touchAction = 'manipulation'; // suppress double-tap zoom on mobile

  document.body.style.margin = '0';
  document.body.style.overflow = 'hidden';
  document.body.style.backgroundColor = '#111';
  document.body.appendChild(canvas);

  R.canvas = canvas;
  R.ctx    = canvas.getContext('2d');

  // --- initialise game state ------------------------------------------
  R.state = {
    phase:          'menu',        // 'menu' | 'countdown' | 'racing' | 'finished'
    time:           0,             // total elapsed seconds (unscaled)
    countdownTimer: R.CONFIG.COUNTDOWN_DURATION,
    raceTime:       0,             // seconds since race started
    bestLap:        Infinity,      // best lap time in seconds
    finishTimer:    0,             // seconds elapsed in 'finished' phase
    playerLap:      0,
    playerFinished: false
  };

  // --- camera ---------------------------------------------------------
  R.camera = R.camera || { x: 0, y: 0, zoom: 1 };

  // --- input (default object if system not yet loaded) ----------------
  R.input = R.input || {
    throttle: 0, brake: 0, steer: 0, boost: 0,
    _keys: {}
  };

  // --- bootstrap subsystems (safe — each is a no-op if missing) --------
  _callIfExists('initInput');
  _callIfExists('initAudio');
  _callIfExists('initTrack');
  _callIfExists('initPlayer');
  _callIfExists('initAI');
  _callIfExists('initHUD');
  _callIfExists('initEffects');
  _callIfExists('initScenery');

  // --- fire up the game loop ------------------------------------------
  requestAnimationFrame(R.loop);
};

// ---------------------------------------------------------------------------
// R.loop(timestamp) — Main game loop
// ---------------------------------------------------------------------------

/**
 * Called every frame via requestAnimationFrame.
 * Calculates delta-time, runs updates, renders, and re-queues itself.
 *
 * @param {DOMHighResTimeStamp} timestamp RAF timestamp in ms
 */
R.loop = function (timestamp) {
  // --- delta-time with spiral-of-death protection ---------------------
  if (R._lastTimestamp === undefined) {
    R._lastTimestamp = timestamp;
    R._dt            = 0;
  }
  const rawDt = timestamp - R._lastTimestamp;
  R._lastTimestamp = timestamp;
  const dt = Math.min(rawDt, R.CONFIG.MAX_DT) / 1000; // seconds

  // --- update phase ---------------------------------------------------
  _callIfExists('updateInput');

  R.updateStateMachine(dt);

  const racing = R.state.phase === 'racing';

  if (typeof R.updatePlayer === 'function' && racing) {
    R.updatePlayer(dt);
  }
  if (typeof R.updateAI === 'function' && racing) {
    R.updateAI(dt);
  }

  if (typeof R.updateCamera === 'function') {
    R.updateCamera(dt);
  }

  _callIfExists('updateEffects');
  _callIfExists('updateHUD');
  // updateEffects gets dt so call with argument if function expects it
  if (typeof R.updateEffects === 'function') {
    R.updateEffects(dt);
  }

  // --- render phase ---------------------------------------------------
  R.render();

  // --- schedule next frame --------------------------------------------
  requestAnimationFrame(R.loop);
};

// ---------------------------------------------------------------------------
// R.updateStateMachine(dt) — Phase transitions
// ---------------------------------------------------------------------------

/**
 * Advances the game state machine one tick.
 *
 * Phases:
 *   'menu'      — wait for Enter or Space, then start countdown
 *   'countdown' — tick down to 0, then start race
 *   'racing'    — race is live; lap-completion check drives transitions
 *   'finished'  — hold for FINISH_DELAY seconds, then allow restart
 *
 * @param {number} dt Delta-time in seconds
 */
R.updateStateMachine = function (dt) {
  const input = R.input;
  const state = R.state;

  switch (state.phase) {

    // ---- menu ----------------------------------------------------------
    case 'menu':
      // Listen for Enter (keyCode 13) or Space (32)
      if (input._keys && (input._keys['Enter'] || input._keys[' '] || input._keys['Space'])) {
        state.phase          = 'countdown';
        state.countdownTimer = R.CONFIG.COUNTDOWN_DURATION;
        state.time           = 0;
        // consume so a held key doesn't immediately skip countdown
        input._keys['Enter'] = false;
        input._keys[' ']     = false;
        input._keys['Space'] = false;
      }
      break;

    // ---- countdown -----------------------------------------------------
    case 'countdown':
      state.countdownTimer -= dt;
      if (state.countdownTimer <= 0) {
        state.countdownTimer = 0;
        state.phase          = 'racing';
        state.raceTime       = 0;
        state.playerLap      = 0;
        state.playerFinished = false;
        state.bestLap        = Infinity;
      }
      break;

    // ---- racing --------------------------------------------------------
    case 'racing':
      state.raceTime += dt;

      // Check whether the player has finished all laps.
      // R.track.totalLaps defaults to 3 if not configured.
      const totalLaps = (R.track && R.track.totalLaps) ? R.track.totalLaps : 3;
      if (state.playerFinished) {
        state.phase        = 'finished';
        state.finishTimer  = 0;
      }
      break;

    // ---- finished ------------------------------------------------------
    case 'finished':
      state.finishTimer += dt;
      // After the delay, Enter / Space returns to menu (or restarts)
      if (state.finishTimer >= R.CONFIG.FINISH_DELAY) {
        if (input._keys && (input._keys['Enter'] || input._keys[' '] || input._keys['Space'])) {
          state.phase          = 'menu';
          state.finishTimer    = 0;
          state.raceTime       = 0;
          state.playerLap      = 0;
          state.playerFinished = false;
          state.bestLap        = Infinity;
          input._keys['Enter'] = false;
          input._keys[' ']     = false;
          input._keys['Space'] = false;
        }
      }
      break;

    default:
      // Unknown phase — reset to menu safely
      state.phase = 'menu';
      break;
  }
};

// ---------------------------------------------------------------------------
// R.render() — Render pipeline
// ---------------------------------------------------------------------------

/**
 * Clears the canvas and runs the full ordered render pass:
 *   sky → track → scenery → cars → effects → HUD → overlay
 */
R.render = function () {
  const ctx = R.ctx;
  if (!ctx) return;

  // Clear entire canvas
  ctx.clearRect(0, 0, R.CONFIG.CANVAS_WIDTH, R.CONFIG.CANVAS_HEIGHT);

  // Ordered render calls — each is optional (safe no-op if missing)
  _callIfExists('renderSky');
  _callIfExists('renderTrack');
  _callIfExists('renderScenery');
  _callIfExists('renderCars');
  _callIfExists('renderEffects');
  _callIfExists('renderHUD');
  _callIfExists('renderOverlay');
};

// ---------------------------------------------------------------------------
// R.updateCamera(dt) — Smooth camera follow
// ---------------------------------------------------------------------------

/**
 * Lerp the camera toward the player car for smooth following.
 * Uses R.CONFIG.CAMERA_SMOOTH for the interpolation factor and
 * R.CONFIG.CAMERA_OFFSET_Y to shift the camera vertically.
 *
 * @param {number} dt Delta-time in seconds (available for future use)
 */
R.updateCamera = function (dt) {
  // Guard: need a player object with x,y
  const player = R.player;
  if (!player) return;

  const cam   = R.camera;
  const smooth = R.CONFIG.CAMERA_SMOOTH;
  const offsetY = R.CONFIG.CAMERA_OFFSET_Y;

  // If the camera hasn't been initialised at all, snap immediately
  if (cam.x === undefined || cam.y === undefined) {
    cam.x = player.x;
    cam.y = player.y + offsetY;
    return;
  }

  cam.x += (player.x - cam.x) * smooth;
  cam.y += (player.y + offsetY - cam.y) * smooth;
};

// ---------------------------------------------------------------------------
// Math utilities
// ---------------------------------------------------------------------------

/**
 * Linear interpolation between a and b.
 * @param {number} a Start value
 * @param {number} b End value
 * @param {number} t Interpolation factor [0, 1]
 * @returns {number} Interpolated value
 */
R.lerp = function (a, b, t) {
  return a + (b - a) * t;
};

/**
 * Clamp a value between min and max (inclusive).
 * @param {number} v  Value to clamp
 * @param {number} lo Lower bound
 * @param {number} hi Upper bound
 * @returns {number} Clamped value
 */
R.clamp = function (v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
};

/**
 * Euclidean distance between two 2D points.
 * @param {number} x1
 * @param {number} y1
 * @param {number} x2
 * @param {number} y2
 * @returns {number} Distance
 */
R.dist = function (x1, y1, x2, y2) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  return Math.sqrt(dx * dx + dy * dy);
};

/**
 * Random float in [min, max).
 * @param {number} min Lower bound (inclusive)
 * @param {number} max Upper bound (exclusive)
 * @returns {number} Random value
 */
R.randomRange = function (min, max) {
  return min + Math.random() * (max - min);
};

// ---------------------------------------------------------------------------
// Exports (all attached to window.R)
// ---------------------------------------------------------------------------
// init, loop, updateStateMachine, render, updateCamera
// lerp, clamp, dist, randomRange
// aiCars[], particles[], sceneryObjects[]

