// === engine.js — Racing Game ===
// Main game loop, state machine, canvas bootstrap, camera, math utilities,
// built-in keyboard/touch input, FPS tracking, and responsive scaling.
// Attaches all exports to window.R.

window.R = window.R || {};

// ---------------------------------------------------------------------------
// Default engine constants (extend R.CONFIG if not already set)
// ---------------------------------------------------------------------------
R.CONFIG = R.CONFIG || {};
R.CONFIG.CANVAS_WIDTH        = R.CONFIG.CANVAS_WIDTH        || 1280;
R.CONFIG.CANVAS_HEIGHT       = R.CONFIG.CANVAS_HEIGHT       || 720;
R.CONFIG.MAX_DT              = R.CONFIG.MAX_DT              || 33;     // ms — cap to avoid spiral of death
R.CONFIG.CAMERA_SMOOTH       = R.CONFIG.CAMERA_SMOOTH       || 0.08;   // lerp factor per frame
R.CONFIG.CAMERA_OFFSET_Y     = R.CONFIG.CAMERA_OFFSET_Y     || -80;    // vertical offset from player
R.CONFIG.FINISH_DELAY        = R.CONFIG.FINISH_DELAY        || 5;      // seconds before restart allowed
R.CONFIG.COUNTDOWN_DURATION  = R.CONFIG.COUNTDOWN_DURATION  || 3;      // seconds of countdown
R.CONFIG.FPS_SAMPLE_COUNT    = R.CONFIG.FPS_SAMPLE_COUNT    || 60;     // rolling window for FPS average

// ---------------------------------------------------------------------------
// Object pools / shared arrays — pre-allocated, no allocations in hot path
// ---------------------------------------------------------------------------
R.aiCars          = [];
R.particles       = [];
R.sceneryObjects  = [];

// ---------------------------------------------------------------------------
// Debug flags (set R.debug = true before init() to enable)
// ---------------------------------------------------------------------------
R.debug = R.debug || false;

// ---------------------------------------------------------------------------
// Internal helpers (not exported on R)
// ---------------------------------------------------------------------------

/**
 * Safely invoke a function on R if it exists; otherwise no-op.
 * Used so the engine runs even when optional module files are missing.
 * @param {string} fnName Property name on R to call
 * @param {...*}   args   Optional arguments forwarded to the function
 */
function _callIfExists(fnName) {
  var args = Array.prototype.slice.call(arguments, 1);
  var fn = R[fnName];
  if (typeof fn === 'function') {
    fn.apply(R, args);
  }
}

/**
 * Capture a key-event code into the canonical R.input._keys map.
 * Normalises Space and Enter for cross-browser consistency.
 * @param {string}  code   KeyboardEvent.code string (e.g. "Space", "Enter", "KeyA")
 * @param {boolean} pressed true = keydown, false = keyup
 */
function _setKeyState(code, pressed) {
  if (!R.input || !R.input._keys) return;
  // Normalise: treat both "Space" (code) and " " (legacy) as the same action key
  R.input._keys[code] = pressed;
  if (code === 'Space') {
    R.input._keys[' '] = pressed;
  }
  if (code === 'Enter') {
    // Enter is already canonical
  }
  // Map arrows and WASD to throttle / brake / steer via input module,
  // but also store raw key state so engine fallback works.
}

// ---------------------------------------------------------------------------
// Keyboard / touch input — built-in fallback (overridden by initInput if
// the input module is loaded, but guarantees input always works)
// ---------------------------------------------------------------------------

/**
 * Attach DOM event listeners for keyboard and touch.
 * Safe to call multiple times (idempotent guard).
 */
function _attachBuiltinInput() {
  if (R._inputAttached) return;
  R._inputAttached = true;

  // Ensure input object exists
  R.input = R.input || { throttle: 0, brake: 0, steer: 0, boost: 0, _keys: {} };

  // --- Keyboard ------------------------------------------------------------
  window.addEventListener('keydown', function (e) {
    _setKeyState(e.code, true);
    // Prevent default for game keys so the page doesn't scroll
    if (e.code === 'ArrowUp'   || e.code === 'ArrowDown' ||
        e.code === 'ArrowLeft' || e.code === 'ArrowRight' ||
        e.code === 'Space'     || e.code === 'Enter') {
      e.preventDefault();
    }
    // Map to throttle / brake / steer for arrow-key driving
    if (e.code === 'ArrowUp')    { R.input.throttle = 1; }
    if (e.code === 'ArrowDown')  { R.input.brake    = 1; }
    if (e.code === 'ArrowLeft')  { R.input.steer    = -1; }
    if (e.code === 'ArrowRight') { R.input.steer    =  1; }
  });

  window.addEventListener('keyup', function (e) {
    _setKeyState(e.code, false);
    if (e.code === 'ArrowUp')    { R.input.throttle = 0; }
    if (e.code === 'ArrowDown')  { R.input.brake    = 0; }
    if (e.code === 'ArrowLeft' || e.code === 'ArrowRight') { R.input.steer = 0; }
  });

  // --- Touch (mobile swipe detection) --------------------------------------
  var touchStartX = 0;
  var touchStartY = 0;
  var touchActive = false;

  R.canvas.addEventListener('touchstart', function (e) {
    e.preventDefault();
    var t = e.touches[0];
    touchStartX = t.clientX;
    touchStartY = t.clientY;
    touchActive = true;
  }, { passive: false });

  R.canvas.addEventListener('touchmove', function (e) {
    e.preventDefault();
    if (!touchActive) return;
    var t = e.touches[0];
    var dx = t.clientX - touchStartX;
    var dy = t.clientY - touchStartY;
    // Horizontal steering
    if (Math.abs(dx) > 10) {
      R.input.steer = R.clamp(dx / 80, -1, 1);
    }
    // Vertical throttle / brake
    if (dy < -20) {
      R.input.throttle = R.clamp(Math.abs(dy) / 80, 0, 1);
      R.input.brake = 0;
    } else if (dy > 20) {
      R.input.brake = R.clamp(dy / 80, 0, 1);
      R.input.throttle = 0;
    }
    // Short upward swipe = boost
    if (dy < -50 && Math.abs(dx) < 20) {
      R.input.boost = 1;
    }
  }, { passive: false });

  R.canvas.addEventListener('touchend', function (e) {
    e.preventDefault();
    touchActive = false;
    R.input.steer    = 0;
    R.input.throttle = 0;
    R.input.brake    = 0;
    R.input.boost    = 0;
  }, { passive: false });
}

// ---------------------------------------------------------------------------
// R.init() — Bootstrap the entire game
// ---------------------------------------------------------------------------

/**
 * Create the canvas element, initialise all subsystems, and start the
 * game loop.  Safe to call multiple times — subsequent calls are ignored.
 *
 * Usage:
 *   window.addEventListener('DOMContentLoaded', function () { R.init(); });
 *   // or: <body onload="R.init()">
 */
R.init = function () {
  if (R._initialised) return;
  R._initialised = true;

  // --- canvas element ------------------------------------------------------
  var canvas = document.createElement('canvas');
  canvas.id          = 'gameCanvas';
  canvas.width       = R.CONFIG.CANVAS_WIDTH;
  canvas.height      = R.CONFIG.CANVAS_HEIGHT;
  canvas.style.display      = 'block';
  canvas.style.margin       = '0 auto';
  canvas.style.background   = '#000';
  canvas.style.maxWidth     = '100%';
  canvas.style.maxHeight    = '100vh';
  canvas.style.touchAction  = 'manipulation'; // suppress double-tap zoom

  // CSS for full-window centering via flexbox on body
  document.body.style.margin          = '0';
  document.body.style.padding         = '0';
  document.body.style.overflow        = 'hidden';
  document.body.style.backgroundColor = '#111';
  document.body.style.display         = 'flex';
  document.body.style.alignItems      = 'center';
  document.body.style.justifyContent  = 'center';
  document.body.style.minHeight       = '100vh';
  document.body.appendChild(canvas);

  R.canvas = canvas;
  R.ctx    = canvas.getContext('2d');

  // If we have no 2d context something is very wrong
  if (!R.ctx) {
    console.error('[engine] Failed to obtain CanvasRenderingContext2D');
    return;
  }

  // --- initialise game state -----------------------------------------------
  R.state = {
    phase:           'menu',          // 'menu' | 'countdown' | 'racing' | 'finished' | 'paused'
    time:            0,               // total elapsed seconds (unscaled wall-clock)
    countdownTimer:  R.CONFIG.COUNTDOWN_DURATION,
    raceTime:        0,               // seconds since race started
    bestLap:         Infinity,        // best lap time in seconds
    finishTimer:     0,               // seconds elapsed in 'finished' phase
    playerLap:       0,
    playerFinished:  false,
    prevPhase:       null             // previous phase — used to detect transitions
  };

  // --- camera --------------------------------------------------------------
  R.camera = R.camera || { x: 0, y: 0, zoom: 1 };

  // --- attach built-in input handlers --------------------------------------
  _attachBuiltinInput();

  // --- bootstrap subsystems (safe — each call is a no-op if missing) --------
  _callIfExists('initInput');
  _callIfExists('initAudio');
  _callIfExists('initTrack');
  _callIfExists('initPlayer');
  _callIfExists('initAI');
  _callIfExists('initHUD');
  _callIfExists('initEffects');
  _callIfExists('initScenery');

  // --- register lifecycle handlers -----------------------------------------
  _attachLifecycleHandlers();

  // --- fire up the game loop -----------------------------------------------
  R._frameCount  = 0;
  R._fpsSamples  = [];
  R._fpsAverage  = 60;
  R._lastTimestamp = undefined;
  requestAnimationFrame(R.loop);

  console.log('[engine] Initialised — canvas ' +
    R.CONFIG.CANVAS_WIDTH + '×' + R.CONFIG.CANVAS_HEIGHT +
    ', waiting for input to start.');
};

/**
 * Attach window-level handlers: visibility change (pause on tab switch),
 * resize (responsive scaling), and beforeunload (clean shutdown).
 */
function _attachLifecycleHandlers() {
  // --- pause when tab loses focus ------------------------------------------
  document.addEventListener('visibilitychange', function () {
    if (document.hidden && R.state.phase === 'racing') {
      R.state.prevPhase = 'racing';
      R.state.phase     = 'paused';
    } else if (!document.hidden && R.state.phase === 'paused' && R.state.prevPhase === 'racing') {
      R.state.phase     = 'racing';
      R.state.prevPhase = null;
    }
  });

  // --- responsive canvas scaling -------------------------------------------
  window.addEventListener('resize', _onResize);
  _onResize(); // initial sizing
}

/**
 * Scale the canvas element to fit the viewport while preserving aspect ratio.
 * The internal resolution stays fixed; only the CSS display size changes.
 */
function _onResize() {
  var canvas  = R.canvas;
  if (!canvas) return;
  var maxW    = window.innerWidth;
  var maxH    = window.innerHeight;
  var ratio   = R.CONFIG.CANVAS_WIDTH / R.CONFIG.CANVAS_HEIGHT;
  var displayW, displayH;

  if (maxW / maxH > ratio) {
    // viewport is wider than canvas ratio — constrained by height
    displayH = maxH;
    displayW = maxH * ratio;
  } else {
    // viewport is taller — constrained by width
    displayW = maxW;
    displayH = maxW / ratio;
  }

  canvas.style.width  = Math.floor(displayW) + 'px';
  canvas.style.height = Math.floor(displayH) + 'px';
}

// ---------------------------------------------------------------------------
// R.loop(timestamp) — Main game loop
// ---------------------------------------------------------------------------

/**
 * Called every frame via requestAnimationFrame.
 * Calculates delta-time, runs updates, renders, tracks FPS, and re-queues.
 *
 * @param {DOMHighResTimeStamp} timestamp RAF timestamp in ms
 */
R.loop = function (timestamp) {
  // --- delta-time with spiral-of-death protection -------------------------
  if (R._lastTimestamp === undefined) {
    R._lastTimestamp = timestamp;
    R._dt            = 0;
  }
  var rawDt = timestamp - R._lastTimestamp;
  R._lastTimestamp = timestamp;
  var dt = Math.min(rawDt, R.CONFIG.MAX_DT) / 1000; // convert ms → seconds

  // --- FPS tracking (rolling average) -------------------------------------
  R._frameCount++;
  R._fpsSamples.push(rawDt);
  if (R._fpsSamples.length > R.CONFIG.FPS_SAMPLE_COUNT) {
    R._fpsSamples.shift();
  }
  // Recalculate average every few frames to amortise cost
  if (R._frameCount % 15 === 0) {
    var sum = 0;
    for (var i = 0; i < R._fpsSamples.length; i++) {
      sum += R._fpsSamples[i];
    }
    R._fpsAverage = R._fpsSamples.length > 0
      ? Math.round(1000 / (sum / R._fpsSamples.length))
      : 60;
  }

  // --- track raw time -----------------------------------------------------
  R.state.time += dt;

  // --- update phase --------------------------------------------------------
  _callIfExists('updateInput');

  R.updateStateMachine(dt);

  var racing = R.state.phase === 'racing';

  if (racing) {
    if (typeof R.updatePlayer === 'function') R.updatePlayer(dt);
    if (typeof R.updateAI === 'function')      R.updateAI(dt);
  }

  if (typeof R.updateCamera === 'function')    R.updateCamera(dt);
  if (typeof R.updateEffects === 'function')   R.updateEffects(dt);
  if (typeof R.updateHUD === 'function')       R.updateHUD(dt);

  // --- render phase --------------------------------------------------------
  R.render();

  // --- schedule next frame -------------------------------------------------
  requestAnimationFrame(R.loop);
};

// ---------------------------------------------------------------------------
// R.updateStateMachine(dt) — Phase transitions
// ---------------------------------------------------------------------------

/**
 * Advances the game state machine one tick.
 *
 * Phases:
 *   'menu'      — wait for Enter / Space / tap, then start countdown
 *   'countdown' — tick down from COUNTDOWN_DURATION to 0, then start race
 *   'racing'    — race is live; player lap completion drives → finished
 *   'finished'  — hold for FINISH_DELAY seconds, then allow restart
 *   'paused'    — tab-switch pause; resumes automatically
 *
 * @param {number} dt Delta-time in seconds
 */
R.updateStateMachine = function (dt) {
  var input = R.input;
  var state = R.state;
  if (!input || !state) return;

  switch (state.phase) {

    // ---- menu --------------------------------------------------------------
    case 'menu':
      if (_isConfirmPressed()) {
        state.phase          = 'countdown';
        state.countdownTimer = R.CONFIG.COUNTDOWN_DURATION;
        state.time           = 0;
        state.playerLap      = 0;
        state.playerFinished = false;
        state.bestLap        = Infinity;
        state.raceTime       = 0;
        _consumeConfirmKeys();
      }
      break;

    // ---- countdown ---------------------------------------------------------
    case 'countdown':
      state.countdownTimer -= dt;
      if (state.countdownTimer <= 0) {
        state.countdownTimer = 0;
        state.phase          = 'racing';
        state.raceTime       = 0;
        state.playerLap      = 0;
        state.playerFinished = false;
        state.bestLap        = Infinity;
      }
      break;

    // ---- racing ------------------------------------------------------------
    case 'racing':
      state.raceTime += dt;

      // Check whether the player has finished all laps.
      // R.track.totalLaps defaults to 3 if not configured.
      var totalLaps = (R.track && R.track.totalLaps) ? R.track.totalLaps : 3;
      if (state.playerFinished || state.playerLap >= totalLaps) {
        state.playerFinished = true;
        state.phase          = 'finished';
        state.finishTimer    = 0;
        // Record final race time
        if (state.raceTime < state.bestLap || state.bestLap === Infinity) {
          state.bestLap = state.raceTime;
        }
      }

      // Allow pause toggle during racing (Escape or P)
      if (input._keys && (input._keys['Escape'] || input._keys['KeyP'])) {
        state.prevPhase = 'racing';
        state.phase     = 'paused';
        input._keys['Escape'] = false;
        input._keys['KeyP']   = false;
      }
      break;

    // ---- paused ------------------------------------------------------------
    case 'paused':
      // Resume with Escape or P
      if (input._keys && (input._keys['Escape'] || input._keys['KeyP'])) {
        state.phase     = state.prevPhase || 'racing';
        state.prevPhase = null;
        input._keys['Escape'] = false;
        input._keys['KeyP']   = false;
      }
      break;

    // ---- finished ----------------------------------------------------------
    case 'finished':
      state.finishTimer += dt;
      // After the delay, Enter / Space / tap returns to menu
      if (state.finishTimer >= R.CONFIG.FINISH_DELAY) {
        if (_isConfirmPressed()) {
          state.phase          = 'menu';
          state.finishTimer    = 0;
          state.raceTime       = 0;
          state.playerLap      = 0;
          state.playerFinished = false;
          state.bestLap        = Infinity;
          state.prevPhase      = null;
          _consumeConfirmKeys();
        }
      }
      break;

    default:
      // Unknown phase — reset to menu safely
      state.phase     = 'menu';
      state.prevPhase = null;
      break;
  }
};

// ---------------------------------------------------------------------------
// Input helpers used by state machine (not exported)
// ---------------------------------------------------------------------------

/**
 * Check whether a confirm action (Enter, Space, or touch tap) is currently held.
 * @returns {boolean}
 */
function _isConfirmPressed() {
  var k = R.input._keys;
  if (!k) return false;
  return !!(k['Enter'] || k[' '] || k['Space'] || k['TouchTap']);
}

/**
 * Consume all confirm-action keys so a held key doesn't re-trigger immediately.
 */
function _consumeConfirmKeys() {
  var k = R.input._keys;
  if (!k) return;
  k['Enter']    = false;
  k[' ']        = false;
  k['Space']    = false;
  k['TouchTap'] = false;
}

// ---------------------------------------------------------------------------
// R.render() — Render pipeline
// ---------------------------------------------------------------------------

/**
 * Clears the canvas and runs the full ordered render pass:
 *   sky → track → scenery → cars → effects → HUD → overlay → debug
 */
R.render = function () {
  var ctx = R.ctx;
  if (!ctx) return;

  // Save and restore context state around the full frame to avoid
  // bleed from any module that forgets to reset transforms.
  ctx.save();

  // Clear entire canvas with a flat colour (sky modules will paint over it)
  ctx.clearRect(0, 0, R.CONFIG.CANVAS_WIDTH, R.CONFIG.CANVAS_HEIGHT);

  // Apply camera transform for world-space rendering
  _applyCameraTransform(ctx);

  // Ordered render calls — each is optional (safe no-op if module missing)
  if (typeof R.renderSky     === 'function') R.renderSky(ctx);
  if (typeof R.renderTrack   === 'function') R.renderTrack(ctx);
  if (typeof R.renderScenery === 'function') R.renderScenery(ctx);
  if (typeof R.renderCars    === 'function') R.renderCars(ctx);
  if (typeof R.renderEffects === 'function') R.renderEffects(ctx);

  // Reset camera transform before drawing screen-space HUD/overlay
  ctx.restore();
  ctx.save();

  if (typeof R.renderHUD     === 'function') R.renderHUD(ctx);
  if (typeof R.renderOverlay === 'function') R.renderOverlay(ctx);

  // Debug overlay (FPS, state, object counts) — rendered last, on top
  if (R.debug) {
    _renderDebugOverlay(ctx);
  }

  ctx.restore();
};

/**
 * Apply camera translation and zoom to the canvas context.
 * Modules that render in world-space should be called between
 * _applyCameraTransform and the ctx.restore() in R.render().
 * @param {CanvasRenderingContext2D} ctx
 */
function _applyCameraTransform(ctx) {
  if (!R.camera) return;
  var cam = R.camera;
  // Translate so the camera position is centred on screen
  ctx.translate(R.CONFIG.CANVAS_WIDTH / 2, R.CONFIG.CANVAS_HEIGHT / 2);
  ctx.scale(cam.zoom || 1, cam.zoom || 1);
  ctx.translate(-cam.x, -cam.y);
}

/**
 * Render a debug HUD showing FPS, current phase, elapsed time, and
 * live object counts for the pools.
 * @param {CanvasRenderingContext2D} ctx
 */
function _renderDebugOverlay(ctx) {
  var x = 10;
  var y = R.CONFIG.CANVAS_HEIGHT - 10;
  ctx.save();
  ctx.font = '12px monospace';
  ctx.fillStyle = 'rgba(0,255,0,0.85)';
  ctx.textBaseline = 'bottom';
  ctx.textAlign = 'left';

  var lines = [
    'FPS: '     + R._fpsAverage,
    'Phase: '   + R.state.phase,
    'Time: '    + R.state.raceTime.toFixed(2) + 's',
    'Lap: '     + R.state.playerLap,
    'AI cars: ' + R.aiCars.length,
    'Particles: ' + R.particles.length,
    'Scenery: ' + R.sceneryObjects.length
  ];

  for (var i = 0; i < lines.length; i++) {
    ctx.fillText(lines[i], x, y - (lines.length - 1 - i) * 16);
  }
  ctx.restore();
}

// ---------------------------------------------------------------------------
// R.updateCamera(dt) — Smooth camera follow
// ---------------------------------------------------------------------------

/**
 * Lerp the camera toward the player car for smooth following.
 * Uses R.CONFIG.CAMERA_SMOOTH for the interpolation factor and
 * R.CONFIG.CAMERA_OFFSET_Y to shift the camera vertically.
 *
 * Also applies camera-shake if R.camera._shakeMagnitude is set (cleared
 * each frame by the effects system).
 *
 * @param {number} dt Delta-time in seconds
 */
R.updateCamera = function (dt) {
  var player = R.player;
  if (!player) return;

  var cam    = R.camera;
  var smooth = R.CONFIG.CAMERA_SMOOTH;
  var offY   = R.CONFIG.CAMERA_OFFSET_Y;

  // Frame-rate-aware lerp: t = 1 - (1 - smooth)^(dt * 60)
  // This keeps the feel consistent regardless of framerate.
  var t = 1 - Math.pow(1 - smooth, dt * 60);

  // If the camera hasn't been set at all, snap immediately
  if (cam.x === undefined || cam.y === undefined) {
    cam.x = player.x;
    cam.y = player.y + offY;
    return;
  }

  // Smooth follow
  cam.x += (player.x - cam.x) * t;
  cam.y += (player.y + offY - cam.y) * t;

  // Camera shake (decaying magnitude, applied as random offset each frame)
  if (cam._shakeMagnitude && cam._shakeMagnitude > 0.01) {
    cam.x += (Math.random() - 0.5) * cam._shakeMagnitude * 2;
    cam.y += (Math.random() - 0.5) * cam._shakeMagnitude * 2;
    cam._shakeMagnitude *= 0.85; // exponential decay
  } else {
    cam._shakeMagnitude = 0;
  }
};

// ---------------------------------------------------------------------------
// Math utilities
// ---------------------------------------------------------------------------

/**
 * Linear interpolation between a and b.
 * @param {number} a Start value
 * @param {number} b End value
 * @param {number} t Interpolation factor [0, 1]
 * @returns {number} Interpolated value
 */
R.lerp = function (a, b, t) {
  return a + (b - a) * t;
};

/**
 * Clamp a value between lo and hi (inclusive).
 * @param {number} v  Value to clamp
 * @param {number} lo Lower bound
 * @param {number} hi Upper bound
 * @returns {number} Clamped value
 */
R.clamp = function (v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
};

/**
 * Euclidean distance between two 2D points.
 * @param {number} x1
 * @param {number} y1
 * @param {number} x2
 * @param {number} y2
 * @returns {number} Distance
 */
R.dist = function (x1, y1, x2, y2) {
  var dx = x2 - x1;
  var dy = y2 - y1;
  return Math.sqrt(dx * dx + dy * dy);
};

/**
 * Random float in [min, max).
 * @param {number} min Lower bound (inclusive)
 * @param {number} max Upper bound (exclusive)
 * @returns {number} Random value
 */
R.randomRange = function (min, max) {
  return min + Math.random() * (max - min);
};

/**
 * Move a value toward a target by a fixed step (no overshoot).
 * Useful for steering return-to-centre, speed decay, etc.
 * @param {number} current Current value
 * @param {number} target  Desired value
 * @param {number} step    Maximum change per call
 * @returns {number} New value
 */
R.approach = function (current, target, step) {
  if (current < target) {
    return Math.min(current + step, target);
  }
  return Math.max(current - step, target);
};

/**
 * Remap a value from one range to another.
 * @param {number} v    Input value
 * @param {number} inA  Input range low
 * @param {number} inB  Input range high
 * @param {number} outA Output range low
 * @param {number} outB Output range high
 * @returns {number} Remapped value
 */
R.remap = function (v, inA, inB, outA, outB) {
  var t = (v - inA) / (inB - inA);
  return outA + t * (outB - outA);
};

/**
 * Format seconds into mm:ss.cc (centiseconds).
 * @param {number} seconds
 * @returns {string} Formatted time string
 */
R.formatTime = function (seconds) {
  if (!isFinite(seconds) || seconds < 0) return '--:--.--';
  var m  = Math.floor(seconds / 60);
  var s  = Math.floor(seconds % 60);
  var cs = Math.floor((seconds % 1) * 100);
  return (m < 10 ? '0' : '') + m + ':' +
         (s < 10 ? '0' : '') + s + '.' +
         (cs < 10 ? '0' : '') + cs;
};

// ---------------------------------------------------------------------------
// Exports (all attached to window.R)
// ---------------------------------------------------------------------------
// init, loop, updateStateMachine, render, updateCamera
// lerp, clamp, dist, randomRange, approach, remap, formatTime
// aiCars[], particles[], sceneryObjects[]

// === engine.js — Racing Game ===
// Main game loop, state machine, canvas bootstrap, camera, and math utilities.
// Attaches all exports to window.R.

window.R = window.R || {};

// ---------------------------------------------------------------------------
// Default engine constants (extend R.CONFIG if not already set)
// ---------------------------------------------------------------------------
R.CONFIG = R.CONFIG || {};
R.CONFIG.CANVAS_WIDTH        = R.CONFIG.CANVAS_WIDTH        || 1280;
R.CONFIG.CANVAS_HEIGHT       = R.CONFIG.CANVAS_HEIGHT       || 720;
R.CONFIG.MAX_DT              = R.CONFIG.MAX_DT              || 33;     // ms cap — spiral-of-death protection
R.CONFIG.CAMERA_SMOOTH       = R.CONFIG.CAMERA_SMOOTH       || 0.08;   // lerp factor per frame
R.CONFIG.CAMERA_OFFSET_Y     = R.CONFIG.CAMERA_OFFSET_Y     || -80;    // vertical screen offset from player
R.CONFIG.FINISH_DELAY        = R.CONFIG.FINISH_DELAY        || 5;      // seconds before restart allowed
R.CONFIG.COUNTDOWN_DURATION  = R.CONFIG.COUNTDOWN_DURATION  || 3;      // seconds

// ---------------------------------------------------------------------------
// Object pools / shared arrays — pre-allocated, no allocations in hot path
// ---------------------------------------------------------------------------
R.aiCars          = [];
R.particles       = [];
R.sceneryObjects  = [];

// ---------------------------------------------------------------------------
// Internal helpers (not exported on R)
// ---------------------------------------------------------------------------

/**
 * Safely invoke a zero-argument function on R if it exists; otherwise no-op.
 * Allows the engine to boot even when optional module files are missing.
 * @param {string} fnName Property name on R
 */
function _callIfExists(fnName) {
  if (typeof R[fnName] === 'function') {
    R[fnName]();
  }
}

// ---------------------------------------------------------------------------
// Built-in keyboard fallback — guarantees R.input._keys exists even if the
// input module is not loaded.  initInput() may override/extend this.
// ---------------------------------------------------------------------------

function _attachBuiltinInput() {
  if (R._inputAttached) return;
  R._inputAttached = true;

  R.input = R.input || { throttle: 0, brake: 0, steer: 0, boost: 0, _keys: {} };

  window.addEventListener('keydown', function (e) {
    R.input._keys[e.code] = true;
    // Prevent default for game keys so the page doesn't scroll
    if (e.code === 'ArrowUp'   || e.code === 'ArrowDown' ||
        e.code === 'ArrowLeft' || e.code === 'ArrowRight' ||
        e.code === 'Space'     || e.code === 'Enter') {
      e.preventDefault();
    }
    // Map arrows directly to driving inputs
    if (e.code === 'ArrowUp')    { R.input.throttle = 1; }
    if (e.code === 'ArrowDown')  { R.input.brake    = 1; }
    if (e.code === 'ArrowLeft')  { R.input.steer    = -1; }
    if (e.code === 'ArrowRight') { R.input.steer    =  1; }
  });

  window.addEventListener('keyup', function (e) {
    R.input._keys[e.code] = false;
    if (e.code === 'ArrowUp')    { R.input.throttle = 0; }
    if (e.code === 'ArrowDown')  { R.input.brake    = 0; }
    if (e.code === 'ArrowLeft' || e.code === 'ArrowRight') { R.input.steer = 0; }
  });
}

// ---------------------------------------------------------------------------
// R.init() — Bootstrap the entire game
// ---------------------------------------------------------------------------

/**
 * Create the canvas element (1280×720), append to document.body, get 2d
 * context, initialise all subsystems, and start the game loop.
 *
 * Safe to call multiple times — subsequent calls are ignored.
 *
 * Usage:
 *   window.addEventListener('DOMContentLoaded', function () { R.init(); });
 */
R.init = function () {
  if (R._initialised) return;
  R._initialised = true;

  // --- canvas element ---------------------------------------------------
  var canvas = document.createElement('canvas');
  canvas.id            = 'gameCanvas';
  canvas.width         = R.CONFIG.CANVAS_WIDTH;
  canvas.height        = R.CONFIG.CANVAS_HEIGHT;
  canvas.style.display     = 'block';
  canvas.style.margin      = '0 auto';
  canvas.style.background  = '#000';
  canvas.style.maxWidth    = '100%';
  canvas.style.maxHeight   = '100vh';
  canvas.style.touchAction = 'manipulation';

  document.body.style.margin          = '0';
  document.body.style.overflow        = 'hidden';
  document.body.style.backgroundColor = '#111';
  document.body.style.display         = 'flex';
  document.body.style.alignItems      = 'center';
  document.body.style.justifyContent  = 'center';
  document.body.style.minHeight       = '100vh';
  document.body.appendChild(canvas);

  R.canvas = canvas;
  R.ctx    = canvas.getContext('2d');

  // --- game state -------------------------------------------------------
  R.state = {
    phase:           'menu',          // 'menu' | 'countdown' | 'racing' | 'finished'
    time:            0,               // wall-clock elapsed seconds
    countdownTimer:  R.CONFIG.COUNTDOWN_DURATION,
    raceTime:        0,               // seconds since race start
    bestLap:         Infinity,
    finishTimer:     0,
    playerLap:       0,
    playerFinished:  false
  };

  // --- camera -----------------------------------------------------------
  R.camera = R.camera || { x: 0, y: 0, zoom: 1 };

  // --- built-in keyboard support ----------------------------------------
  _attachBuiltinInput();

  // --- bootstrap subsystems (each call is a no-op if the module is not loaded)
  _callIfExists('initInput');
  _callIfExists('initAudio');
  _callIfExists('initTrack');
  _callIfExists('initPlayer');
  _callIfExists('initAI');
  _callIfExists('initHUD');
  _callIfExists('initEffects');
  _callIfExists('initScenery');

  // --- responsive canvas scaling ----------------------------------------
  window.addEventListener('resize', _onResize);
  _onResize();

  // --- launch -----------------------------------------------------------
  R._lastTimestamp = undefined;
  requestAnimationFrame(R.loop);
};

/**
 * Scale the canvas CSS size to fit the viewport while keeping the internal
 * resolution fixed at CANVAS_WIDTH × CANVAS_HEIGHT.
 */
function _onResize() {
  var c = R.canvas;
  if (!c) return;
  var ratio = R.CONFIG.CANVAS_WIDTH / R.CONFIG.CANVAS_HEIGHT;
  var w, h;
  if (window.innerWidth / window.innerHeight > ratio) {
    h = window.innerHeight;
    w = h * ratio;
  } else {
    w = window.innerWidth;
    h = w / ratio;
  }
  c.style.width  = Math.floor(w) + 'px';
  c.style.height = Math.floor(h) + 'px';
}

// ---------------------------------------------------------------------------
// R.loop(timestamp) — Main game loop
// ---------------------------------------------------------------------------

/**
 * Called every frame via requestAnimationFrame.
 * Calculates dt (capped at MAX_DT ms), runs all update and render passes,
 * then re-queues itself for the next frame.
 *
 * @param {DOMHighResTimeStamp} timestamp RAF timestamp in ms
 */
R.loop = function (timestamp) {
  // --- delta-time with spiral-of-death protection -----------------------
  if (R._lastTimestamp === undefined) {
    R._lastTimestamp = timestamp;
  }
  var rawDt = timestamp - R._lastTimestamp;
  R._lastTimestamp = timestamp;
  var dt = Math.min(rawDt, R.CONFIG.MAX_DT) / 1000; // ms → seconds

  // --- update phase -----------------------------------------------------
  _callIfExists('updateInput');

  R.updateStateMachine(dt);

  var racing = R.state.phase === 'racing';

  if (racing) {
    if (typeof R.updatePlayer === 'function') { R.updatePlayer(dt); }
    if (typeof R.updateAI === 'function')     { R.updateAI(dt); }
  }

  if (typeof R.updateCamera === 'function')  { R.updateCamera(dt); }
  if (typeof R.updateEffects === 'function') { R.updateEffects(dt); }
  if (typeof R.updateHUD === 'function')     { R.updateHUD(dt); }

  // --- render phase -----------------------------------------------------
  R.render();

  // --- schedule next frame ----------------------------------------------
  requestAnimationFrame(R.loop);
};

// ---------------------------------------------------------------------------
// R.updateStateMachine(dt) — Phase transitions
// ---------------------------------------------------------------------------

/**
 * Advances the game state machine one tick.
 *
 *   'menu'      — wait for Enter/Space → countdown
 *   'countdown' — tick down to 0 → racing
 *   'racing'    — raceTime increments; when playerFinished → finished
 *   'finished'  — hold FINISH_DELAY seconds, then Enter/Space → menu
 *
 * @param {number} dt Delta-time in seconds
 */
R.updateStateMachine = function (dt) {
  var input = R.input;
  var state = R.state;
  if (!input || !state) return;

  switch (state.phase) {

    // ---- menu ----------------------------------------------------------
    case 'menu':
      if (input._keys && (input._keys['Enter'] || input._keys[' '] || input._keys['Space'])) {
        state.phase          = 'countdown';
        state.countdownTimer = R.CONFIG.COUNTDOWN_DURATION;
        state.raceTime       = 0;
        state.playerLap      = 0;
        state.playerFinished = false;
        state.bestLap        = Infinity;
        // Consume keys so a held key doesn't skip the countdown
        input._keys['Enter'] = false;
        input._keys[' ']     = false;
        input._keys['Space'] = false;
      }
      break;

    // ---- countdown -----------------------------------------------------
    case 'countdown':
      state.countdownTimer -= dt;
      if (state.countdownTimer <= 0) {
        state.countdownTimer = 0;
        state.phase          = 'racing';
        state.raceTime       = 0;
        state.playerLap      = 0;
        state.playerFinished = false;
        state.bestLap        = Infinity;
      }
      break;

    // ---- racing --------------------------------------------------------
    case 'racing':
      state.raceTime += dt;

      // Check finish condition
      if (state.playerFinished) {
        state.phase       = 'finished';
        state.finishTimer = 0;
      }
      break;

    // ---- finished ------------------------------------------------------
    case 'finished':
      state.finishTimer += dt;
      if (state.finishTimer >= R.CONFIG.FINISH_DELAY) {
        if (input._keys && (input._keys['Enter'] || input._keys[' '] || input._keys['Space'])) {
          state.phase          = 'menu';
          state.finishTimer    = 0;
          state.raceTime       = 0;
          state.playerLap      = 0;
          state.playerFinished = false;
          state.bestLap        = Infinity;
          input._keys['Enter'] = false;
          input._keys[' ']     = false;
          input._keys['Space'] = false;
        }
      }
      break;

    default:
      // Unknown phase — reset to menu
      state.phase = 'menu';
      break;
  }
};

// ---------------------------------------------------------------------------
// R.render() — Render pipeline
// ---------------------------------------------------------------------------

/**
 * Clears the canvas and runs the full ordered render pass:
 *   sky → track → scenery → cars → effects → HUD → overlay
 *
 * Applies camera transform for world-space layers and restores it before
 * screen-space HUD/overlay layers.
 */
R.render = function () {
  var ctx = R.ctx;
  if (!ctx) return;

  ctx.save();

  // Clear the full canvas
  ctx.clearRect(0, 0, R.CONFIG.CANVAS_WIDTH, R.CONFIG.CANVAS_HEIGHT);

  // --- world-space layers (camera-relative) -----------------------------
  _applyCameraTransform(ctx);

  if (typeof R.renderSky     === 'function') { R.renderSky(ctx); }
  if (typeof R.renderTrack   === 'function') { R.renderTrack(ctx); }
  if (typeof R.renderScenery === 'function') { R.renderScenery(ctx); }
  if (typeof R.renderCars    === 'function') { R.renderCars(ctx); }
  if (typeof R.renderEffects === 'function') { R.renderEffects(ctx); }

  // --- screen-space layers ----------------------------------------------
  ctx.restore();
  ctx.save();

  if (typeof R.renderHUD     === 'function') { R.renderHUD(ctx); }
  if (typeof R.renderOverlay === 'function') { R.renderOverlay(ctx); }

  ctx.restore();
};

/**
 * Apply the camera translation and zoom to the canvas context.
 * World-space render calls should happen between apply and restore.
 * @param {CanvasRenderingContext2D} ctx
 */
function _applyCameraTransform(ctx) {
  var cam = R.camera;
  if (!cam) return;
  ctx.translate(R.CONFIG.CANVAS_WIDTH / 2, R.CONFIG.CANVAS_HEIGHT / 2);
  ctx.scale(cam.zoom || 1, cam.zoom || 1);
  ctx.translate(-cam.x, -cam.y);
}

// ---------------------------------------------------------------------------
// R.updateCamera(dt) — Smooth camera follow
// ---------------------------------------------------------------------------

/**
 * Lerp the camera toward the player car for smooth following.
 *
 * Uses a frame-rate-independent lerp so the feel is consistent at any FPS:
 *   t = 1 - (1 - CAMERA_SMOOTH) ^ (dt * 60)
 *   camera.x += (player.x - camera.x) * t
 *   camera.y += (player.y + CAMERA_OFFSET_Y - camera.y) * t
 *
 * @param {number} dt Delta-time in seconds
 */
R.updateCamera = function (dt) {
  var player = R.player;
  if (!player) return;

  var cam    = R.camera;
  var smooth = R.CONFIG.CAMERA_SMOOTH;
  var offY   = R.CONFIG.CAMERA_OFFSET_Y;

  // Frame-rate-independent lerp factor
  var t = 1 - Math.pow(1 - smooth, dt * 60);

  // Snap on first frame (camera not yet positioned)
  if (cam.x === undefined || cam.y === undefined) {
    cam.x = player.x;
    cam.y = player.y + offY;
    return;
  }

  cam.x += (player.x - cam.x) * t;
  cam.y += (player.y + offY - cam.y) * t;
};

// ---------------------------------------------------------------------------
// Math utilities
// ---------------------------------------------------------------------------

/**
 * Linear interpolation between a and b.
 * @param {number} a Start value
 * @param {number} b End value
 * @param {number} t Interpolation factor [0, 1]
 * @returns {number} Interpolated value
 */
R.lerp = function (a, b, t) {
  return a + (b - a) * t;
};

/**
 * Clamp a value between lo and hi (inclusive).
 * @param {number} v  Value to clamp
 * @param {number} lo Lower bound
 * @param {number} hi Upper bound
 * @returns {number} Clamped value
 */
R.clamp = function (v, lo, hi) {
  return v < lo ? lo : v > hi ? hi : v;
};

/**
 * Euclidean distance between two 2D points.
 * @param {number} x1 First point x
 * @param {number} y1 First point y
 * @param {number} x2 Second point x
 * @param {number} y2 Second point y
 * @returns {number} Distance
 */
R.dist = function (x1, y1, x2, y2) {
  var dx = x2 - x1;
  var dy = y2 - y1;
  return Math.sqrt(dx * dx + dy * dy);
};

/**
 * Random float in [min, max).
 * @param {number} min Lower bound (inclusive)
 * @param {number} max Upper bound (exclusive)
 * @returns {number} Random value
 */
R.randomRange = function (min, max) {
  return min + Math.random() * (max - min);
};

